    display:flex;justify-content:space-between;align-items:baseline;
    padding:18px 24px;flex-wrap:wrap;gap:8px;
  }
  header h1{font-size:15px;font-weight:800;letter-spacing:.14em;text-transform:uppercase;}
  header p{font-size:13px;color:#cfcfcb;letter-spacing:.08em;text-transform:uppercase;}

  /* ---- hero: the composition itself ---- */
  .hero{
    border:var(--line) solid var(--black);
    display:grid; gap:var(--line);
    background:var(--black);
    grid-template-columns:1.6fr 1fr 1.3fr;
    grid-template-rows:minmax(150px,28vh) minmax(120px,22vh) minmax(150px,26vh);
    margin:32px auto; max-width:920px;
