  .b-yellow{background:var(--yellow);grid-column:3;grid-row:3;}
  .b-blue{background:var(--blue);color:var(--white);grid-column:1;grid-row:3;}
  .b-red h2{font-size:clamp(26px,4vw,42px);font-weight:800;line-height:1.12;}
  .b-red .yr{display:block;font-size:clamp(18px,2.6vw,26px);font-weight:600;margin-top:6px;}
  .b-red .meta{font-size:13px;letter-spacing:.1em;text-transform:uppercase;margin-top:14px;opacity:.92;}
  .b-yellow p,.b-blue p{font-size:13px;font-weight:600;line-height:1.4;}
  .b-yellow p{color:var(--black);}
  .b-blue p{color:var(--white);}
  @media (max-width:640px){
    .hero{grid-template-columns:1fr 1fr;grid-template-rows:auto;}
    .b-white-tl{grid-row:auto;min-height:120px;}
    .b-red{grid-column:1/3;grid-row:auto;}
  }

