  section{padding:56px 0 8px;}
  .kicker{
    display:inline-block;background:var(--black);color:var(--white);
    font-size:12px;font-weight:800;letter-spacing:.16em;text-transform:uppercase;
    padding:4px 10px;margin-bottom:16px;
  }
  .kicker.k-red{background:var(--red);} .kicker.k-blue{background:var(--blue);} .kicker.k-yellow{background:var(--yellow);color:var(--black);}
  section h2{font-size:clamp(24px,3.4vw,34px);font-weight:800;line-height:1.15;margin-bottom:14px;}
  section p{max-width:64ch;font-size:16px;}
  .rule{height:var(--line);background:var(--black);margin:44px 0 0;}

